BASE = r'F:\Projects\BoardGames\Корабль призрак'


def patch(p, pairs):
    s = open(p, encoding='utf-8').read()
    for a, b in pairs:
        if a not in s:
            raise SystemExit('НЕТ в %s: %s' % (os.path.basename(p), a[:100]))
        s = s.replace(a, b, 1)
    open(p, 'w', encoding='utf-8').write(s)


